<script>
const incidentEntries=document.querySelector('#incidentEntries');
let incidentIndex=1;
document.querySelector('#addIncident')?.addEventListener('click',()=>{const fragment=document.querySelector('#incidentTemplate').content.cloneNode(true);fragment.querySelectorAll('[name]').forEach((field)=>{field.name=field.name.replaceAll('INDEX',incidentIndex);});fragment.querySelector('.incident-title').textContent=`Insiden #${incidentIndex+1}`;incidentEntries.append(fragment);incidentIndex++;});
incidentEntries?.addEventListener('click',(event)=>{if(event.target.closest('.remove-incident'))event.target.closest('.incident-entry').remove();});
incidentEntries?.addEventListener('change',(event)=>{if(!event.target.matches('.incident-area'))return;const entry=event.target.closest('.incident-entry');const camera=entry.querySelector('.incident-camera');[...camera.options].forEach((option,index)=>{if(index===0)return;const match=option.dataset.areaId===event.target.value;option.hidden=!match;option.disabled=!match;});camera.value='';});

document.querySelectorAll('.signature-box').forEach((box)=>{
    const canvas=box.querySelector('.signature-pad');
    const context=canvas.getContext('2d');
    const value=box.querySelector('.signature-data');
    let drawing=false;
    let imageVersion=0;
    const resize=()=>{const saved=value.value;const version=++imageVersion;const ratio=window.devicePixelRatio||1;const width=canvas.clientWidth;const height=120;canvas.width=width*ratio;canvas.height=height*ratio;context.setTransform(ratio,0,0,ratio,0,0);context.lineWidth=2;context.lineCap='round';context.lineJoin='round';context.strokeStyle='#172033';if(saved){const image=new Image();image.onload=()=>{if(version===imageVersion&&value.value===saved)context.drawImage(image,0,0,width,height);};image.src=saved;}};
    const point=(event)=>{const rect=canvas.getBoundingClientRect();return {x:event.clientX-rect.left,y:event.clientY-rect.top};};
    canvas.addEventListener('pointerdown',(event)=>{drawing=true;canvas.setPointerCapture(event.pointerId);const p=point(event);context.beginPath();context.moveTo(p.x,p.y);});
    canvas.addEventListener('pointermove',(event)=>{if(!drawing)return;const p=point(event);context.lineTo(p.x,p.y);context.stroke();value.value=canvas.toDataURL('image/png');});
    const stop=()=>{if(!drawing)return;drawing=false;value.value=canvas.toDataURL('image/png');};
    canvas.addEventListener('pointerup',stop);canvas.addEventListener('pointercancel',stop);
    box.querySelector('.clear-signature').addEventListener('click',()=>{imageVersion++;value.value='';context.save();context.setTransform(1,0,0,1,0,0);context.clearRect(0,0,canvas.width,canvas.height);context.restore();});
    resize();window.addEventListener('resize',resize);
});

</script>
<?= $this->endSection() ?>
